/**
 * The published user guide's table of contents.
 *
 * Generated by `scripts/sync_user_guide.py` from `docs/user-guide/README.md`
 * — the guide's own index — so the order and the one-line summaries here are
 * the ones a reader sees on GitHub. Nothing in the frontend decides them.
 */
export interface GuideChapter {
  /** URL segment: `/guide/<slug>`. The filename without `.md`. */
  slug: string
  /** The published markdown file, fetched as a static asset. */
  file: string
  /** Chapter number as printed in the index; empty for an unnumbered page. */
  number: string
  /** Title with the number stripped, so the two can be set in different type. */
  title: string
  /** The index's own sentence about the chapter. May be empty. */
  summary: string
}

/** One "Part" of the guide, as grouped by the index's headings. */
export interface GuidePart {
  title: string
  chapters: GuideChapter[]
}

export interface GuideManifest {
  /** The index file, rendered as the guide's front page. */
  index: string
  parts: GuidePart[]
}
